#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using PVZEngine.Tools;

namespace MVZ2.GameContent.Buffs.Projectiles
{
    [AutoBuffDefinition(VanillaBuffNames.Projectile.prismPylonProjectileOrange)]
    public class PrismPylonProjectileOrangeBuff : BuffDefinition
    {
        public PrismPylonProjectileOrangeBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new IntModifier(VanillaProjectileProps.MAX_PIERCE_COUNT, IntegerOperator.Add, 1));
            AddTrigger(VanillaLevelCallbacks.POST_PROJECTILE_HIT, PostProjectileHitCallback);
        }
        private void PostProjectileHitCallback(VanillaLevelCallbacks.PostProjectileHitParams args, CallbackResult result)
        {
            var entity = args.hit.Projectile;
            if (!entity.HasBuff(this))
                return;
            var other = args.hit.Other;
            using var bufferItem = ListPool<Entity>.Rent();
            var targetBuffer = bufferItem.Value;
            HomingProjectileBuff.FindAllNextTargets(entity, targetBuffer);
            var target = targetBuffer.OrderBy(t => (entity.GetCenter() - t.GetCenter()).sqrMagnitude).FirstOrDefault(t => t != other);
            if (!target.ExistsAndAlive())
                return;
            var targetPosition = HomingProjectileBuff.GetTargetPosition(target);
            entity.Velocity = (targetPosition - entity.Position).normalized * entity.Velocity.magnitude;
        }
    }
}
